import { useId, useState, type FormEvent } from 'react';
import {
  JxAlert,
  JxButton,
  JxField,
  JxInput,
  JxSelect,
  JxSwitch,
} from '@jinx-ui/react';

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель — только чтение' },
  { value: 'editor', label: 'Редактор — может менять содержимое' },
  { value: 'admin', label: 'Администратор — управляет участниками' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const formId = useId();
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const trimmed = email.trim();
  const isValid = EMAIL_PATTERN.test(trimmed);
  const error = touched && !isValid ? 'Похоже, это не адрес. Пример: anna@example.com' : undefined;

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!isValid) {
      setTouched(true);
      return;
    }
    setInvitedEmail(trimmed);
    setEmail('');
    setTouched(false);
  }

  return (
    <div style={{ display: 'grid', gap: 'var(--jx-space-4)', maxWidth: 'var(--jx-size-md)' }}>
      {invitedEmail !== null && (
        <JxAlert
          variant="success"
          title="Приглашение отправлено"
          onClose={() => setInvitedEmail(null)}
        >
          {invitedEmail} получит доступ к команде.
        </JxAlert>
      )}

      <form
        onSubmit={handleSubmit}
        noValidate
        style={{ display: 'grid', gap: 'var(--jx-space-4)' }}
      >
        <JxField
          label="Рабочая почта"
          htmlFor={`${formId}-email`}
          hint="Приглашение действует 7 дней."
          error={error}
          required
        >
          <JxInput
            id={`${formId}-email`}
            type="email"
            name="email"
            placeholder="anna@example.com"
            autoComplete="email"
            invalid={Boolean(error)}
            value={email}
            onValueChange={setEmail}
            onBlur={() => setTouched(true)}
          />
        </JxField>

        <JxField label="Роль в команде" htmlFor={`${formId}-role`}>
          <JxSelect
            id={`${formId}-role`}
            name="role"
            value={role}
            onValueChange={setRole}
            options={ROLES}
          />
        </JxField>

        <JxSwitch
          id={`${formId}-notify`}
          name="notify"
          label="Отправить уведомление на почту"
          value={notify}
          onValueChange={setNotify}
        />

        <JxButton type="submit" variant="primary" disabled={!isValid}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

